const meta = {
  component: HoverCard,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Use a visual preview to show sighted users the content behind a link.

**Import:** `@/registry/erbium/ui/hover-card`

## Usage

```tsx
import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from "@/registry/erbium/ui/hover-card"
import {{ Button }} from "@/registry/erbium/ui/button"
```

```tsx
<HoverCard>
  <HoverCardTrigger render={<Button variant="link">Hover</Button>} />
  <HoverCardContent>Accessible components for building your next interface.</HoverCardContent>
</HoverCard>
```

## Composition

Use the following composition to build a `HoverCard`:

```text
HoverCard
├── HoverCardTrigger
└── HoverCardContent
```

## Interaction ownership

Keep preview content tied to the current trigger. Remounting a trigger while the card is closed should not start an opening transition. A hover card is a preview, so avoid adding focus traps or application overlay contexts.

The surface provides the shared compact panel gutter. Compose content inside that gutter without adding another padded wrapper.

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Preview Card](https://base-ui.com/react/components/preview-card)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof HoverCard>;

export default { ...meta, title: "Components/Hover Card",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

